import attr

from .connection_details import SshServiceDetails


@attr.s(cmp=False)
class HardwareController(object):
    """
    :param SshServiceDetails ssh_connection_details: SshServiceDetails class instance object
    """
    default_ssh_connection_details = attr.ib(type=SshServiceDetails)
    type = attr.ib(init=False)

    def __attrs_post_init__(self):
        self.type = self.__class__.__name__

    def __taf_contract_ssh__(self):
        return self.default_ssh_connection_details.__taf_contract_ssh__()


@attr.s(cmp=False)
class AmiaFanHardwareController(HardwareController):
    """
    physical machine(raspberry pi) used to turn on/off fans in airscale/amia
    """


@attr.s(cmp=False)
class GPSPowerHardwareController(HardwareController):
    """
    physical machine(raspberry pi) used to turn on/off gps module
    """


@attr.s(cmp=False)
class Cleware(HardwareController):
    """
    physical machine(cleware) used to turn on/off ALD
    """
